def solve(payload):
    import math
    samples = payload["samples"]
    if not samples:
        return {"error": "empty_samples"}
    origin = samples[0]
    offsets = [value - origin for value in samples]
    average_offset = math.fsum(offsets) / len(offsets)
    variance = math.fsum((value - average_offset) ** 2 for value in offsets) / len(offsets)
    return {"mean": origin + average_offset, "variance": variance}

